/* ---------- voice (speech synthesis) ---------- */
const voice={on:true,ok:"speechSynthesis" in window,lang:{ar:"ar-SA",fr:"fr-FR",en:"en-US",ur:"ur-PK",id:"id-ID",tr:"tr-TR",bn:"bn-BD",ha:"ha-NG",hi:"hi-IN",fa:"fa-IR",ms:"ms-MY",es:"es-ES"}};
