["pointerdown","touchend","keydown","click"].forEach(ev=>document.addEventListener(ev,()=>{try{CTTS.unlock()}catch(_){}},{capture:true,passive:true}));
function spk(){if(state.turnLang)return state.turnLang;return profile.speakLang&&profile.speakLang!=="auto"?profile.speakLang:null}
function uiLang(){return state.turnLang||profile.readLang||state.lang||"ar"}
function speak(text,opt={}){
  if(state.signMode&&!opt.force){try{navigator.vibrate&&navigator.vibrate([80,40,80])}catch(_){}return Promise.resolve()}
  if((!voice.on&&!opt.force)||!text)return Promise.resolve();
  const codeC=voice.lang[opt.lang||spk()||uiLang()]||"ar-SA";const plain=ttsPrep(text).join(" ");
  if(CTTS.ok()&&plain&&plain.length<=900&&!CTTS.failed){if(!opt.queue)stopSpeak();return CTTS.play(plain,codeC.slice(0,2)).then(okp=>{if(okp){CTTS.fails=0;return true}if(CTTS.unlocked){CTTS.fails=(CTTS.fails||0)+1;if(CTTS.fails>=2){CTTS.failed=Date.now();log("sup","الصوت العصبي غير متاح الآن من البوابة","يعود إلى صوت الجوال دقيقتين ثم يحاول من جديد")}}return speakLocal(text,opt)}).catch(()=>{CTTS.fails=(CTTS.fails||0)+1;if(CTTS.fails>=2)CTTS.failed=Date.now();return speakLocal(text,opt)})}
  return speakLocal(text,opt)}
function speakLocal(text,opt={}){if(!voice.ok)return Promise.resolve();if(CTTS.failed&&Date.now()-CTTS.failed>120000)CTTS.failed=0;
  return new Promise(res=>{try{const code=voice.lang[opt.lang||spk()||uiLang()]||"ar-SA";const v=pickVoice(code);const parts=ttsPrep(text);if(!parts.length){res();return}
    let done=false;const fin=()=>{if(!done){done=true;res()}};let left=parts.length;
    const us=parts.map(pt=>{const u=new SpeechSynthesisUtterance(pt);u.lang=code;if(v)u.voice=v;u.rate=opt.rate||1.0;u.pitch=1;u.onend=()=>{if(--left<=0)fin()};u.onerror=e=>{voice.err=e.error||"error";voiceStatus();if(--left<=0)fin()};u.onstart=()=>{voice.err="";voice.spoke=true;voiceStatus()};return u});
    if(!opt.queue)speechSynthesis.cancel();
    const go=()=>{try{if(speechSynthesis.paused)speechSynthesis.resume();us.forEach(u=>speechSynthesis.speak(u))}catch(e){voice.err=String(e);voiceStatus();fin()}};
    if(opt.force)go();else setTimeout(go,60);
    setTimeout(fin,Math.min(30000,2500+String(text).length*110));
  }catch(_){res()}})
}
function voiceStatus(){const el=$("#voiceStat");if(!el)return;let vs=[];try{vs=speechSynthesis.getVoices()}catch(_){}
  const ar=vs.filter(v=>v.lang.startsWith("ar")).map(v=>v.name);const fr=vs.filter(v=>v.lang.startsWith("fr")).length;
  el.innerHTML=(voice.cloud?"الصوت العصبي من البوابة يعمل · ":"")+(!voice.ok?"المتصفح لا يدعم النطق (Web Speech)":`الأصوات في هذا الجهاز: ${vs.length}${ar.length?` · عربي: ${esc(ar.slice(0,2).join("، "))}`:" · <b style='color:var(--crit)'>لا يوجد صوت عربي مثبت</b>"}${fr?" · فرنسي متاح":""}${voice.err?` · <b style='color:var(--crit)'>خطأ: ${esc(voice.err)}</b>`:voice.spoke?" · نطق بنجاح":" · لم ينطق بعد، اضغط 🔊 ثم أرسل رسالة"}`)}
