const KB=[
 {t:"الإحرام وكيف أحرم",s:["ih","au"],k:["الاحرام","كيف احرم","انوي العمره","نيه العمره","صفه الاحرام","متى احرم"],
  a:["الإحرام هو الدخول في عبادة العمرة أو الحج: تنوي الدخول في النسك بقلبك وتبدأ بالتلبية.","يسن قبله الاغتسال والتطيب في البدن دون ثياب الإحرام، وأن يكون بعد صلاة فريضة أو نافلة، ويسن قبل النية قص الأظافر وأخذ ما يشرع أخذه من الشعر.","وتصرح بنسكك في أول تلبيتك فتقول: لبيك اللهم عمرة."]},
 {t:"لباس الإحرام للرجل والمرأة",s:["ih","uv"],k:["لباس الاحرام","ملابس الاحرام","لبس الاحرام","ثياب الاحرام","احرام المراه","المراه تلبس","الازار والرداء","حزام الاحرام"],
  a:["الرجل: إزار يحيط أسفل البدن ورداء يغطي أعلاه، غير مخيطين، ويشرع أن يكونا أبيضين، وله أن يستعمل المشبك أو الحزام ليشد إزاره ويحفظ متاعه.","المرأة: تحرم فيما شاءت من الثياب الساترة، على أن تكون فضفاضة لا تعيق الحركة وليست ثياب زينة."]},
 {t:"الاشتراط عند الإحرام",s:["ih"],k:["الاشتراط","اشترط","حبسني حابس","اخاف ما اكمل","اخاف ما اقدر اكمل"],
  a:["من خاف ألا يتمكن من إتمام نسكه لمرض أو عارض خارج عن إرادته يشرع له أن يقول بعد تحديد نسكه: فإن حبسني حابس فمحلي حيث حبستني.","فإن حصل ما يمنعه من الإتمام جاز له الخروج من الإحرام وليس عليه شيء."]},
 {t:"التلبية: نصها ومتى تنتهي",s:["ih","au"],k:["التلبيه","لبيك اللهم لبيك","صيغه التلبيه","متى اوقف التلبيه","متى تنتهي التلبيه","متى اقطع التلبيه"],
  a:["نصها: لبيك اللهم لبيك، لبيك لا شريك لك لبيك، إن الحمد والنعمة لك والملك، لا شريك لك.","يرفع الرجال أصواتهم بها وتسر النساء.","تبدأ من الإحرام، وتنتهي للمعتمر عند رؤية البيت أو بدء الطواف."]},
 {t:"المواقيت ومن أين أحرم",s:["ih","au"],k:["الميقات","المواقيت","من وين احرم","من اين احرم","ذو الحليفه","ابيار علي","السيل الكبير","قرن المنازل","يلملم","الجحفه","ذات عرق","احرم في الطائره","احرم من الطائره","محاذاه الميقات","احرم من جده","تجاوز الميقات","احرم من مكه"],
  a:["ذو الحليفة (أبيار علي): ميقات أهل المدينة، نحو 420 كلم عن مكة.","الجحفة (رابغ): ميقات أهل الشام ومن في طريقهم، نحو 187 كلم.","قرن المنازل (السيل الكبير): ميقات أهل نجد ومن في طريقهم، نحو 94 كلم.","يلملم (السعدية): ميقات أهل اليمن ومن في طريقهم، نحو 115 كلم.","ذات عرق: ميقات أهل العراق ومن في طريقهم، نحو 92 كلم.","من يسكن بعيدا عن مكة يلزمه الإحرام من هذه المواقيت أو ما يحاذيها، جوا أو برا أو بحرا، ولا يتجاوزها دون إحرام، والطائرات القادمة إلى جدة تعلن موعد محاذاة الميقات.","من كان بين المواقيت ومكة يحرم من مكانه، ومن كان في مكة يحرم للعمرة من أقرب مكان خارج الحرم مثل مسجد عائشة بالتنعيم."]},
 {t:"محظورات الإحرام",s:["ih","au"],k:["محظورات الاحرام","المحظورات","ممنوعات الاحرام","ممنوع في الاحرام","العطر في الاحرام","الطيب في الاحرام","قص الاظافر في الاحرام","تغطيه الراس","النقاب في الاحرام","القفاز","لبس المخيط","تغطي وجهها","تغطيه وجهها","تغطيه الوجه","يجوز في الاحرام","يجوز للمحرم"],
  a:["محظورات عامة: حلق الشعر أو قصه، قص الأظافر، استعمال الطيب في البدن أو الثياب، قتل الصيد، عقد النكاح، الجماع ومقدماته.","للرجال: لبس المخيط وتغطية الرأس.","للنساء: لبس النقاب والقفازين.","وليست من المحظورات: الاغتسال، تضميد الجراح، لبس النعال، وتغطية المرأة وجهها عند حضور الأجانب."]},
 {t:"الوقاية من التسلخ بعد الإحرام",s:["ih","um"],k:["تسلخ","التسلخ","التسلخات","التهاب الفخذ","احتكاك الفخذ"],
  a:["للوقاية: تهوية ثنايا الجسم، والعناية بالنظافة الشخصية، واستخدام المراهم قبل المشي، ووضع بودرة مضادة للفطريات.","وعند الإصابة: اغسل المنطقة جيدا ثم ضع المرهم العلاجي."]},
 {t:"خطوات العمرة",s:["um","au"],k:["خطوات العمره","صفه العمره","كيف اعتمر","كيف اسوي العمره","طريقه العمره","مناسك العمره","اركان العمره","اعمال العمره","كيف العمره"],
  a:["1. الإحرام من الميقات: الرجل في إزار ورداء والمرأة في ثيابها الساترة، والنية بالقلب ثم التلبية: لبيك اللهم عمرة.","2. الطواف حول الكعبة سبعة أشواط، يبدأ بالحجر الأسود وينتهي به، والكعبة عن يسارك.","3. ركعتان خلف مقام إبراهيم إن تيسر، وإلا في أي مكان من المسجد.","4. السعي بين الصفا والمروة سبعة أشواط، يبدأ بالصفا وينتهي بالمروة.","5. الحلق أو التقصير للرجل، والتقصير قدر أنملة للمرأة، وبه تحل من إحرامك."]},
 {t:"كيف أطوف",s:["um","au"],k:["كيف اطوف","صفه الطواف","طريقه الطواف","كيف الطواف","من وين ابدا الطواف","بدايه الطواف","العلامه الخضراء","كم شوط الطواف","اشواط الطواف","الحجر الاسود","الركن اليماني","الطواف على طهاره","دعاء الطواف"],
  a:["يبدأ الطواف من ركن الحجر الأسود، وتوجد علامة خضراء توضح ذلك، وهو عكس عقارب الساعة والكعبة عن يسارك.","تكبر رافعا يدك اليمنى عند محاذاة الحجر الأسود في كل شوط، والأمر تقريبي. وتقبيله سنة لمن تيسر له دون تزاحم، وإلا أشار إليه.","يستحب مسح الركن اليماني باليد إن تيسر دون تقبيل، وإن لم يمكن فلا يشار إليه.","وبين الركن اليماني والحجر الأسود: ربنا آتنا في الدنيا حسنة، وفي الآخرة حسنة، وقنا عذاب النار.","سبعة أشواط، كل شوط من الحجر الأسود وإليه، ويجب أن تكون على طهارة، فالطواف كالصلاة إلا أنه يجوز فيه الكلام."]},
 {t:"سنن الطواف: الاضطباع والرمل",s:["um","au"],k:["الاضطباع","الرمل","اكشف الكتف","كشف الكتف","سنن الطواف","اسرع في الطواف"],
  a:["للرجال: الاضطباع، أي كشف الكتف الأيمن بجعل الرداء تحت الإبط الأيمن وطرفه على الكتف الأيسر، ويغطيه بعد الطواف.","والرمل: الإسراع في المشي مع تقارب الخطى في الأشواط الثلاثة الأولى إن تيسر، مع الحرص على سلامة الطائفين، ولا يسن للنساء.","ومن السنن الإكثار من الدعاء والذكر."]},
 {t:"الطواف في الزحام والأدوار",s:["uv","um"],k:["المطاف مزدحم","زحمه المطاف","المطاف العلوي","الطواف في الادوار","الطواف بالعربه","الطواف بالكرسي","صحن المطاف","من يدخل صحن المطاف"],
  a:["صحن المطاف (الطابق الأرضي) مخصص للمحرمين فقط تيسيرا لحركة الطائفين.","إن وجدت المطاف الأرضي مزدحما فهناك مطاف علوي تصل إليه من عدد من الأبواب والسلالم.","الطواف بالكراسي المتحركة والعربات الكهربائية في الطابق الأول أو الثاني، ولا يسمح بدخولها صحن المطاف.","تجنب السير عكس اتجاه الطواف، والوقوف المفاجئ، وأماكن التدافع.","يوصل إلى المطاف: باب الملك عبدالعزيز، باب الملك فهد، باب السلام، باب العمرة."]},
 {t:"ركعتا الطواف",s:["um","au"],k:["ركعتين الطواف","ركعتي الطواف","ركعتا الطواف","مقام ابراهيم","ماذا اقرا في الركعتين","وين اصلي بعد الطواف"],
  a:["بعد الشوط السابع يغطي الرجل كتفه، ويتجه إلى خلف مقام إبراهيم أو محاذاته إن تيسر، ويقرأ: واتخذوا من مقام إبراهيم مصلى.","يصلي ركعتين: في الأولى بعد الفاتحة سورة الكافرون، وفي الثانية سورة الإخلاص.","وإن لم يتيسر صلاهما في أي مكان من المسجد الحرام تجنبا للزحام، وفي الأدوار العلوية تؤدى من أي مكان في المطاف.","ويسن شرب زمزم بعد الطواف."]},
 {t:"كيف أسعى بين الصفا والمروة",s:["um","au"],k:["كيف اسعى","صفه السعي","طريقه السعي","كيف السعي","اشواط السعي","كم شوط السعي","من وين ابدا السعي","العلمين الاخضرين","الضوء الاخضر","الهروله","ادوار المسعى","دعاء السعي","على الصفا"],
  a:["يبدأ السعي من الصفا وينتهي بالمروة، سبعة أشواط: الذهاب من الصفا إلى المروة شوط والعودة شوط آخر، فالأشواط 1 و3 و5 و7 من الصفا، و2 و4 و6 من المروة.","على الصفا تقرأ: إن الصفا والمروة من شعائر الله، وتستقبل القبلة وتقول: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، لا إله إلا الله وحده، أنجز وعده ونصر عبده وهزم الأحزاب وحده، ثلاث مرات وتدعو بينها، وتفعل على المروة مثل ذلك دون قراءة الآية.","بين العلمين الأخضرين في سقف المسعى يهرول الرجال.","المسعى أدوار: البدروم، والأرضي، والميزانين للعربات الكهربائية، والدور الثاني، وينصح بالأدوار العلوية تجنبا للزحام."]},
 {t:"مسافة السعي ومدته",s:["um"],k:["طول المسعى","مسافه السعي","كم يستغرق السعي","مده السعي","كم متر السعي"],
  a:["طول المسعى 394 مترا، ومجموع الأشواط السبعة نحو 2761 مترا، ومتوسط مدة إكمال السعي من 45 إلى 60 دقيقة."]},
 {t:"كم تستغرق العمرة",s:["uv"],k:["كم تستغرق العمره","مده العمره","كم ساعه العمره","كم تاخذ العمره","وقت العمره كم"],
  a:["مشيا: من ساعتين إلى ثلاث ساعات حسب الزحام.","بالعربات الكهربائية: من ساعة ونصف إلى ساعتين، وقد يمتد انتظار العربة في أوقات الذروة مثل رمضان إلى ساعة إضافية."]},
 {t:"الحلق والتقصير والتحلل",s:["um","hg","au"],k:["الحلق","التقصير","احلق","اقصر شعري","التحلل","اتحلل","كم اقص","كيف تقصر المراه","وين احلق","حلاق","انمله","قص الشعر"],
  a:["الرجل يحلق شعره أو يقصره، والحلق أفضل، وفي عمرة التمتع يقصر ولا يحلق كما ينص دليل العمرة.","المرأة تقص من أطراف شعرها قدر أنملة الإصبع.","لا يشترط القص في المسعى؛ توجد صالونات حلاقة مرخصة في الساحات الخارجية جهة المروة وفي الفنادق والمجمعات المحيطة، وعربات متنقلة للتحلل بجوار باب المروة منها عربتان للنساء بكادر نسائي.","وبالتحلل تنتهي العمرة ويباح ما كان ممنوعا بالإحرام، ولم يرو أن النبي صلى الله عليه وسلم صلى بعد العمرة ركعتين."]},
 {t:"تكرار العمرة والعمرة عن غيري",s:["um"],k:["تكرار العمره","اكرر العمره","عمره ثانيه","عمره عن ميت","عمره لغيري","اهدي عمره","عمره عن امي","عمره عن ابوي","عمره عن والدي"],
  a:["يستحب معاودة العمرة من سفر لآخر، ولم يعرف عن الصحابة تكرارها في السفرة الواحدة إلا لسبب، فينصح الدليل بعدم الإكثار منها في الرحلة نفسها دون حاجة.","ومن أراد عمرة إضافية لنفسه أو لغيره فالأصل أن يفصل بين العمرتين بسفر أو غيره، وقال بعض العلماء بجواز الخروج إلى خارج حدود الحرم والإحرام من مسجد عائشة أو الجعرانة.","وعند العمرة عن غيرك تحدد النية والشخص قبل مغادرة مكان الإحرام، والاكتفاء بعمرة واحدة في المواسم يخفف الزحام."]},
 {t:"تصريح العمرة",s:["um","uv"],k:["تصريح العمره","احتاج تصريح","موعد العمره","حجز العمره","تصريح للعمره"],
  a:["يشترط استخراج تصريح العمرة عبر تطبيق نسك قبل التوجه إلى مكة أو المسجد الحرام: تختار الخدمة واليوم والوقت، ثم يصدر التصريح، وتلتزم بأداء العمرة في موعدها.","وتأكد قبل السفر من سريان اشتراط التصريح عبر تطبيق نسك، واختر الأوقات الأقل زحاما."]},
 {t:"التمتع والقران",s:["um"],k:["التمتع","القران","متمتع","قارن","عمره التمتع","حج التمتع"],
  a:["التمتع: أن يحرم بالعمرة وحدها في أشهر الحج، فإذا أتمها تحلل، ثم يحرم للحج يوم الثامن من ذي الحجة.","القران: أن يحرم بالعمرة والحج معا فيقول: لبيك اللهم حجا وعمرة، ومن شروطه ألا يكون من أهل منطقة المسجد الحرام."]},
 {t:"فضل العمرة",s:["um","uv"],k:["فضل العمره","فضائل العمره","عمره في رمضان","اجر العمره"],
  a:["العمرة إلى العمرة كفارة لما بينهما، وقال النبي صلى الله عليه وسلم: تابعوا بين الحج والعمرة فإنهما ينفيان الفقر والذنوب كما ينفي الكير خبث الحديد.","وعمرة في رمضان تعدل حجة في الثواب والأجر، ولا تسقط فريضة الحج."]},
 {t:"أبواب المسجد الحرام الرئيسية",s:["hg"],m:1,k:["ابواب الحرم","ابواب المسجد الحرام","الابواب الرئيسيه","ارقام الابواب الرئيسيه"],
  a:["الأبواب الرئيسية خمسة، توصل مباشرة إلى صحن الطواف، وفوق كل منها منارتان يستدل بهما: باب الملك عبدالعزيز (1)، باب الفتح (45)، باب العمرة (62)، باب الملك فهد (79)، باب الملك عبدالله (100)."]},
 {t:"حدود الحرم وخصائصه",s:["hg"],k:["حدود الحرم","داخل حدود الحرم","مضاعفه الصلاه","الصلاه بمئه الف","خصائص الحرم","لقطه الحرم"],
  a:["تمتد حدود الحرم إلى التنعيم (6.5 كم من جهة المدينة)، و22 كم على طريق جدة السريع، و17 كم على طريق الليث الجديد، و12.85 كم على طريق الطائف السيل، و15.5 كم على طريق الطائف الهدا.","ومن خصائصه: لا يدخله غير المسلمين، ولا تقطع أشجاره ولا حشائشه، ويحرم صيده، ولا تؤخذ لقطته إلا لمن يعرفها، والصلاة فيه تعدل مائة ألف صلاة فيما سواه."]},
 {t:"أركان الكعبة وما يستلم منها",s:["hg"],k:["اركان الكعبه","الركن الشامي","الركن العراقي","الملتزم","الحطيم","حجر اسماعيل","الشاذروان","ماذا المس من الكعبه"],
  a:["الحجر الأسود: يستحب تقبيله أو استلامه إن تيسر، أو الإشارة إليه دون تزاحم.","الركن اليماني: يستحب استلامه فقط.","الركنان الشامي والعراقي: لا يستلمان.","الحطيم (حجر إسماعيل) منطقة نصف دائرية تعد جزءا من الكعبة، والملتزم جزء من الجدار الشرقي بين الباب والحجر الأسود، والشاذروان بناء داعم يحيط بالكعبة وليس جزءا منها."]},
 {t:"ماء زمزم: الآداب والتعبئة والسفر",s:["ns","uv"],k:["الوضوء بزمزم","اتوضا من زمزم","حافظات زمزم","تعبئه زمزم","اعبي زمزم","زمزم في الشنطه","زمزم في الطائره","زمزم في الحقيبه"],
  a:["حافظات زمزم للشرب فقط وليست للوضوء، ولا تفتح الحافظات، ولا تستعمل الكاسات لغير الشرب.","في المسجد النبوي محطة تعبئة مجانية قرب البوابتين الخارجيتين 309 و310 جنوب المسجد.","وعند السفر لا توضع عبوات زمزم داخل الحقائب المشحونة، وتشحن كأمتعة منفصلة وفق اشتراطات خاصة."]},
 {t:"آداب المسجد الحرام والأخطاء الشائعة",s:["uv"],k:["اداب الحرم","اداب المسجد الحرام","الاخطاء الشائعه","اخطاء شائعه","التصوير في الحرم","احجز مكان في الحرم","ممنوع في الحرم","التمسح بالمقام"],
  a:["ادخل برجلك اليمنى مع دعاء الدخول، وابدأ بالطواف إن كنت معتمرا، وإلا فصل ركعتين تحية المسجد.","لا تحجز مكانا بمتعلقاتك، ولا تصل أو تجلس في الممرات.","اترك الحقائب الكبيرة في الفندق أو مكاتب الأمانات، فيمنع إدخالها.","تجنب التدافع للمس الكعبة أو المقام، والتمسح بالحجر أو المقام.","تجنب الانشغال بالتصوير عن العبادة وتصوير الزوار دون إذن، ومكبرات الصوت مع المجموعات، وحمل الأدوات الحادة، والتجاوب مع المتسولين.","لا تتوضأ من حافظات زمزم، وحافظ على النظافة."]},
 {t:"السلالم المتحركة",s:["um"],k:["السلالم المتحركه","الدرج الكهربائي","السلم الكهربائي","السلم المتحرك"],
  a:["لا تجلس على السلم، وقف بثبات وأمسك الحزام المتحرك، وتحرك فور الوصول.","لا تصعد بالعربات إلا بمساعدة مختص، واحمل الحقيبة الثقيلة بيدك لا على ظهرك، وتنتبه المرأة لعباءتها حتى لا تعلق، ولا تضع قدمك على الفرشاة الجانبية."]},
 {t:"الأطفال في المسجد الحرام وضيافتهم",s:["hg"],m:1,k:["سوار الطفل","اسواره الطفل","الاطفال في الحرم","سعر ضيافه الاطفال","ضيافه الاطفال بكم","عمر ضيافه الاطفال"],
  a:["زود طفلك بسوار فيه اسمه ورقم هاتفك، وخدمة سوار الطفل متاحة في مداخل المسجد الحرام، وأمسك بيده في الزحام، وإن فقدته فتوجه فورا إلى مركز العناية بالأطفال التائهين.","مراكز ضيافة الأطفال الموسمية: الذكور من سنة ونصف إلى ست سنوات، والإناث من سنة ونصف إلى تسع، والساعة الأولى مجانية ثم 15 ريالا لكل ساعة إضافية (بحسب الدليل في موسم رمضان)."]},
 {t:"حفظ الأمتعة في المسجد الحرام",s:["hg","uv"],m:1,k:["حفظ الامتعه","الامانات","مكتب الامانات","اودع الشنطه","شنطه كبيره","الحقائب الكبيره"],
  a:["يمنع إدخال الحقائب الكبيرة إلى الحرمين.","خدمة حفظ الأمتعة في المسجد الحرام: مركزان، مقابل باب 64 مدخل الساحة الغربية (الشبيكة)، وجوار مكتبة مكة المكرمة في الساحة الشرقية، مع 6 نقاط استلام عند الأبواب الرئيسية، وتسجيل بأسوارة ذكية والاستلام بمسح الرمز."]},
 {t:"إجابة السائلين والإفتاء في الحرمين",s:["hg","ns","um"],k:["اسال شيخ","اسال عالم","المفتي","الافتاء","سؤال شرعي","اجابه السائلين","رقم الافتاء","هاتف الافتاء"],
  a:["في المسجد الحرام هواتف للرد على أسئلة المعتمرين في 10 مواقع وبسبع لغات، والرقمان المجانيان لإجابة السائلين: 8001222100 و8001222400.","وفي المسجد النبوي كبائن إفتاء هاتفية عند الأبواب ومواقع إفتاء حضورية، أبرزها عند باب 12 في الدور الأول، والرقمان المجانيان نفسهما يعملان داخل المملكة."]},
 {t:"مراكز نسك عناية",s:["hg","ns"],k:["نسك عنايه","مركز نسك","البطاقه الذكيه","اقدم شكوى","تقديم شكوى"],
  a:["مراكز متخصصة لوزارة الحج والعمرة تقدم الدلالة وخدمات الحج والعمرة، واستقبال الشكاوى والبلاغات، والتوجيه والاستفسار، وإصدار البطاقة الذكية، ويتحدث العاملون فيها 10 لغات، والتواصل على 920002814.","وفي المسجد النبوي مركز نسك عناية قرب البوابة الخارجية 352 شرق المسجد قرب البقيع."]},
 {t:"أرقام مهمة لضيوف الرحمن",s:["hg","uv"],k:["ارقام مهمه","الارقام المهمه","رقم الطوارئ","رقم وزاره الحج","رقم الاستفسارات","رقم الشكاوى","الرقم الموحد","ارقام الطوارئ","رقم الاسعاف"],
  a:["الرقم الموحد لاستفسارات ضيوف الرحمن وشكاواهم (وزارة الحج والعمرة): 1966 داخل المملكة، و920002814 من خارجها بمفتاح 966+.","الحالات الطارئة والخدمات الأمنية: 911.","الاستشارات الطبية: 937."]},
 {t:"قطار الحرمين",s:["um"],k:["قطار الحرمين","محطه القطار","القطار السريع"],
  a:["قطار عالي السرعة يصل بين مكة والمدينة مرورا بأهم المواقع بينهما. محطة مكة في حي الرصيفة على بعد 3.5 كلم من المسجد الحرام، وفيها 4750 موقفا، ومنها حافلات مخصصة وسيارات أجرة إلى الحرم.","الحجز ومعرفة الأمتعة المسموحة من موقع قطار الحرمين، واحضر في الوقت المحدد."]},
 {t:"وصايا صحية للمعتمر",s:["um"],k:["نصائح صحيه","وصايا صحيه","احتياطات صحيه","المشي حافي"],
  a:["خذ قسطا من الراحة عند التعب، وأكثر من شرب السوائل، وتجنب المشي حافي القدمين على البلاط، واستحم قبل العمرة، واستخدم مراهم التسلخ وبودرة مضادة للفطريات.","واحمل أدويتك وأدوية الطوارئ."]},
 {t:"المغادرة والسفر",s:["uv"],k:["المغادره","قبل الرحله بكم ساعه","متى اروح المطار","باور بانك","البطاريات في الشنطه"],
  a:["كن في المطار قبل موعد الإقلاع بأربع ساعات، وتأكد من موعد رحلتك وموعد الخروج من السكن.","البطاريات المتنقلة في حقيبة اليد فقط، ولا توضع عبوات زمزم في الحقائب المشحونة، وراجع قائمة المواد المحظورة على موقع الناقل."]},
 {t:"تطبيق نسك",s:["uv"],k:["تطبيق نسك","التسجيل في نسك","احمل نسك","نسك ايش","نسك وش"],
  a:["التطبيق الرسمي المعتمد من وزارة الحج والعمرة: إصدار تصاريح العمرة والصلاة في الروضة الشريفة، وعرض التصريح ورمز الدخول، وتذكير بالمواعيد، ومعلومات أوقات الذروة.","التسجيل بعد إصدار التأشيرة أو عند الوصول، برقم التأشيرة ورقم الجواز وتاريخ الميلاد، والتفعيل برمز يصل إلى الجوال أو البريد.","احتفظ بصورة من رمز التصريح في جوالك لحالات انقطاع الإنترنت."]},
 {t:"السلام على النبي صلى الله عليه وسلم وصاحبيه",s:["as","ns"],k:["السلام على النبي","السلام على الرسول","زياره القبر","زياره قبر النبي","ماذا اقول عند القبر","المواجهه الشريفه","السلام على ابي بكر","كيف اسلم على النبي"],
  a:["يكون الدخول عبر المسار المخصص من باب السلام (1)، ويوجه الزائر أولا إلى نقطة الدخول ثم يسير في مسار منظم حتى المواجهة الشريفة، ويخرج من باب البقيع (41).","تقف تجاه القبر بأدب وخفض صوت وتقول: السلام عليك يا نبي الله ورحمة الله وبركاته. ثم تتحرك عن يمينك قليلا وتسلم على أبي بكر الصديق رضي الله عنه، ثم عن يمينك قليلا وتسلم على عمر بن الخطاب رضي الله عنه.","وإن أردت الدعاء لنفسك فاستقبل القبلة. ولا يصح التبرك بالقبر ولا رفع الصوت عنده، وتجنب التمسح ومزاحمة المصلين، واستمع لتوجيهات العاملين."]},
 {t:"الروضة الشريفة: الحجز والمواعيد",s:["ar","ns"],k:["الروضه","حجز الروضه","مواعيد الروضه","وقت الروضه","اوقات الروضه","تصريح الروضه","الصلاه في الروضه","حدود الروضه","مساحه الروضه"],
  a:["الروضة ما بين بيت النبي صلى الله عليه وسلم ومنبره، مساحتها نحو 330 مترا مربعا، والصلاة فيها بحجز مسبق عبر تطبيق نسك.","للرجال: من 12:30 بعد منتصف الليل إلى صلاة الفجر، ومن 12:30 ظهرا إلى صلاة العشاء متصلة.","للنساء: من 5:30 صباحا إلى 11:00 صباحا، ومن 9:30 مساء إلى 12:00 منتصف الليل.","الدخول عبر نقطة تفويج الزائرين في الساحات الجنوبية، وللنساء عبر الساحة الجنوبية الشرقية بجوار المرفق 201 وباب الساحات 367. وقد تتغير الأوقات، فتأكد من موعدك في نسك.","والنوافل في الروضة أفضل، أما الفروض فالصف الأول أفضل ولو كان خارج الروضة."]},
 {t:"آداب زيارة المسجد النبوي",s:["an"],k:["اداب المسجد النبوي","اداب زياره المسجد النبوي","دعاء دخول المسجد","ماذا اقول عند دخول المسجد","فضل المسجد النبوي"],
  a:["تطيب والبس أحسن ثيابك، وتطهر في بيتك، وبكر للصلاة، وتجنب إحضار الأمتعة، وادخل من الأبواب المخصصة للرجال أو النساء، واعرف رقم بوابة الساحات.","قدم رجلك اليمنى وقل: بسم الله، والصلاة والسلام على رسول الله، اللهم افتح لي أبواب رحمتك، وصل ركعتين تحية المسجد قبل الجلوس.","تجنب مزاحمة المصلين والجلوس أو الصلاة في الممرات والتمسح بالأبواب والجدران، واستقبل القبلة عند الدعاء، وضع الأحذية في أماكنها، واحجز موعد الروضة مسبقا عبر نسك.","والصلاة فيه أفضل من ألف صلاة فيما سواه إلا المسجد الحرام."]},
 {t:"أبواب المسجد النبوي وأرقامها",s:["ns"],m:2,k:["ابواب المسجد النبوي","ارقام ابواب المسجد النبوي","باب البقيع","باب الرحمه","باب جبريل","ابواب النساء","ابواب الساحات"],
  a:["للمسجد النبوي 100 باب: أبواب المسجد من 1 إلى 42 وبعضها بالحروف، وأبواب الساحات الخارجية من 301 إلى 370، وأبواب مرافق الخدمات من 201 إلى 236.","باب السلام (1) لزيارة القبر، وباب البقيع (41) للخروج بعد السلام، وباب الرحمة (3) للخروج بعد زيارة الروضة، وباب جبريل (40).","ومن أبواب النساء: باب السلطان عبدالمجيد (13)، وباب عمر بن الخطاب (17)، وباب عثمان بن عفان (25)، وباب علي بن أبي طالب (29)."]},
 {t:"مراكز الخدمة حول المسجد النبوي",s:["ns"],m:2,k:["مركز صحي","المركز الصحي","مستوصف","مركز الخدمه الشامله","مكتب التوعيه","مكتب ارشاد التائهين","مكتب المفقودات","المفقودات في المسجد النبوي"],
  a:["مركز صحي الصافية جنوب المسجد عبر البوابتين الخارجيتين 304 و305، ومركز صحي باب جبريل شرق المسجد عبر 358 و359 قرب البقيع.","مكتب إرشاد التائهين جوار باب الساحات 365 ومبنى المرفق 202. والأطفال التائهون: المكتب الرئيسي عند سور البقيع مقابل باب الساحة 354، ومكتبان في مصلى النساء الغربي (13) والشرقي (29).","المفقودات جنوب المسجد قرب البوابتين الخارجيتين 366 و367. ومركز الخدمة الشاملة قرب البوابة 329 شمال المسجد، والمركز الرئيسي للتوعية عند باب 12 غرب المسجد."]},
 {t:"خدمات ذوي الإعاقة وكبار السن في المسجد النبوي",s:["ns"],m:2,k:["اعاره كرسي","الكراسي المتحركه في المسجد النبوي","ذوي الاعاقه في المسجد النبوي","مصلى الصم","الصم والبكم","كبار السن في المسجد النبوي"],
  a:["تعار الكراسي المتحركة مجانا (نحو 2500 كرسي) من مكتبين: قرب البوابة الخارجية 344 شرق المسجد، وقرب البوابتين 308 و309 جنوبه بجوار سقيا زمزم، ويقود عربات الجولف موظفون من منسوبي المسجد.","مصلى مجهز للصم والبكم في السطح الغربي عبر الباب الداخلي 6، يتسع لمئة شخص، مع خطبة الجمعة بلغة الإشارة.","ويدخل ذوو الإعاقة وكبار السن عبر الأبواب المزودة بمنحدرات، وفي جميع مرافق دورات المياه دورات خاصة بهم."]},
 {t:"ترجمة خطبة الجمعة",s:["ns","hg"],k:["ترجمه الخطبه","ترجمه خطبه الجمعه","تردد الترجمه","اذاعه الترجمه","موجه fm"],
  a:["في المسجد النبوي تترجم خطبة الجمعة مباشرة عبر الراديو: الإنجليزية FM 105.5، الأوردية FM 105، الفرنسية FM 99.5، الملايوية FM 99، التركية FM 107، الفارسية FM 107، الهوساوية FM 107.3، وعبر منصة منارة الحرمين وقناة اليوتيوب.","وفي المسجد الحرام عبر منصة منارة الحرمين بترجمة صوتية مباشرة، ومنها الأوردية والفرنسية والملايوية والفارسية والإنجليزية، وتترجم بلغة الإشارة في مصلى توسعة الملك فهد عند باب 64."]},
 {t:"مقبرة البقيع",s:["ns"],k:["البقيع","مقبره البقيع","زياره البقيع"],
  a:["مقبرة المدينة منذ عهد النبي صلى الله عليه وسلم، تقع جنوب شرق المسجد النبوي بمساحة 180 ألف متر مربع، دفن فيها كثير من الصحابة وبعض أمهات المؤمنين، وكان النبي صلى الله عليه وسلم يكثر زيارة أهلها والدعاء لهم."]},
 /* ---------- الحج والمشاعر: من أدلة وزارة الحج والعمرة التوعوية للحج (دليل الحج، دليل الحاج العام، أدلة منى وعرفة ومزدلفة ويوم النحر والجمرات) ---------- */
 {t:"أركان الحج وواجباته",s:["hj"],h:1,k:["اركان الحج","ركن الحج","واجبات الحج","واجب الحج","فروض الحج"],
  a:["أركان الحج أربعة: الإحرام، والوقوف بعرفة، وطواف الإفاضة، والسعي.","واجباته: الإحرام من الميقات، والوقوف بعرفة إلى الغروب، والمبيت بمزدلفة، والمبيت بمنى، ورمي الجمرات، والحلق أو التقصير، وطواف الوداع."]},
 {t:"الاستطاعة في الحج",s:["hj"],h:1,k:["الاستطاعه","الاستطاعه في الحج","الاستطاعه الصحيه","شروط الحج","من يمنع من الحج","الحامل والحج"],
  a:["الاستطاعة شرط أساسي لأداء فريضة الحج، وتشمل الاستطاعة الصحية والبدنية والمالية.","الصحية: الالتزام بتعليمات وزارة الصحة وتقديم شهادة مصدقة تضمن الخلو من أمراض منها: فشل أحد الأعضاء الرئيسة (القلب أو الرئتين أو الكبد أو الكلى)، والأمراض العصبية والنفسية التي تؤثر في الإدراك أو تصحبها إعاقات حركية شديدة، والشيخوخة المصحوبة بالخرف، والشهران الأخيران من الحمل والحمل الخطر، والسرطان النشط تحت العلاج، والأمراض المعدية النشطة.","البدنية: أن يقدر على أداء المناسك بنفسه دون مشقة بالغة، أو ينيب من يحج عنه إن كان عاجزا عجزا دائما. والمالية: نفقة الحج كلها مع نفقة من يعولهم حتى عودته."]},
 {t:"تصريح الحج وبطاقة نسك",s:["hgen"],h:1,k:["تصريح الحج","بطاقه نسك","ضاعت بطاقه نسك","فقدت بطاقه نسك","ضيعت بطاقه نسك","تاشيره الحج","حج بدون تصريح","الحج بدون تصريح","بطاقه نسك الرقميه"],
  a:["تصريح الحج وثيقة إلزامية لحجاج الداخل والخارج، ولا تجيز التأشيرات الأخرى الحج، ويحصل المقيم في المملكة على التصريح بعد شراء الباقة المناسبة عبر تطبيق نسك أو موقع الوزارة. واحذر الوسطاء غير الرسميين.","بطاقة نسك هي تصريح دخولك إلى المشاعر المقدسة والمسجد الحرام، تسلمها شركة تقديم الخدمة مطبوعة بعد وصولك، ونسختها الرقمية في تطبيقي نسك وتوكلنا، فاحملها دائما.","عند فقدانها تواصل مع مقدم الخدمة أو اتصل على 1966، وفعل النسخة الرقمية في تطبيق نسك حلا مؤقتا."]},
 {t:"جدول أعمال الحج يوما بيوم",s:["hj","hgen"],h:1,k:["جدول الحج","ايام الحج","اعمال الحج","خطوات الحج","كيف احج","صفه الحج","مناسك الحج","كيف الحج","برنامج الحج"],
  a:["اليوم الثامن (التروية): يحرم المتمتع بالحج من مكانه، ويتوجه الحجاج إلى منى ويبيتون بها، وتصلى الرباعية قصرا دون جمع.","اليوم التاسع (عرفة): الوقوف بعرفة من بعد الزوال حتى غروب الشمس، ثم الانصراف إلى مزدلفة والمبيت بها.","اليوم العاشر (النحر): رمي جمرة العقبة، وذبح الهدي للمتمتع والقارن، والحلق أو التقصير، وطواف الإفاضة والسعي.","أيام التشريق (11 و12 و13): رمي الجمرات الثلاث كل يوم بعد الزوال والمبيت بمنى، ومن تعجل غادر منى قبل غروب يوم 12.","وقبل مغادرة مكة: طواف الوداع. وفي الاختلافات الفقهية راجع مفتي حملتك، والتزم بجداول النقل والتفويج."]},
 {t:"الإحرام بالحج للمتمتع والمفرد والقارن",s:["hj","hgen"],h:1,k:["الاحرام بالحج","متى احرم بالحج","من اين احرم للحج","من وين احرم للحج","لبيك حجا","نيه الحج","احرم للحج","طواف القدوم","الافراد","المفرد"],
  a:["المتمتع: يطوف ويسعى لعمرته ثم يحلق أو يقصر ويتحلل، ثم يحرم بالحج يوم الثامن من مكانه قائلا: اللهم لبيك حجا، وعليه هدي التمتع.","القارن: يسن له إذا دخل مكة طواف القدوم والسعي بعده، ويكفيه هذا السعي عن سعي الحج، ويبقى على إحرامه حتى يوم النحر فينحر الهدي ثم يحلق أو يقصر.","المفرد: يجوز له التوجه إلى عرفات مباشرة دون طواف القدوم لأنه سنة، وإن طاف وسعى أجزأه السعي ولا يعيده، ويبقى على إحرامه حتى يوم النحر.","وتنتهي التلبية في الحج عند رمي جمرة العقبة."]},
 {t:"منى: حدودها ومكانتها",s:["mn"],h:1,k:["حدود مني","مساحه مني","مشعر مني","سبب تسميه مني","ما هي مني","وش هي مني"],
  a:["منى واد داخل حدود الحرم يمتد من الشرق إلى الغرب وتحيط به الجبال، ويحده وادي محسر شرقا، وتنتهي غربا عند جمرة العقبة.","مساحتها الشرعية نحو 7.82 كيلومتر مربع، والمستغل منها نحو 4.8 كيلومتر مربع لأن الباقي جبال وعرة، وإذا ضاقت بالحجاج جاز السكن في المناطق المجاورة داخل حدود الحرم.","يمكث فيها الحجاج من يوم الثامن، ثم يعودون إليها يوم النحر وأيام التشريق حتى تمام الحج."]},
 {t:"يوم التروية في منى",s:["mn","hj"],h:1,k:["يوم الترويه","اليوم الثامن","الثامن من ذي الحجه","متى نروح مني","المبيت بمني يوم الترويه","ماذا افعل يوم الترويه","وش اسوي يوم الترويه"],
  a:["يمكث أغلب الحجاج في منى يوم الثامن، فيصلون فيها الظهر محرمين ويمكثون حتى فجر التاسع. والمبيت فيها هذا اليوم سنة وليس واجبا، فمن ذهب مباشرة إلى عرفة يوم التاسع فلا حرج عليه.","صل الصلوات في وقتها قصرا مع الجماعة في المخيمات، وأكثر من التلبية وقراءة القرآن، وجهز ما تحتاجه ليوم عرفة، وخذ كفايتك من الراحة.","عند وصولك تأكد من أخذ جميع أمتعتك من الحافلة، وتعرف على مشرف الحملة والخدمات المتوفرة في المخيم."]},
 {t:"مخيمك في منى: لا تضيعه",s:["mn"],h:1,k:["رقم المخيم","وين مخيمي","اين مخيمي","ضاع المخيم","ضيعت المخيم","ضيعت مخيمي","تهت في مني","ضعت في مني","الضياع في مني","المخيمات متشابهه"],
  a:["تعرف على موقع مخيمك ورقمه وبوابته وأقرب معلم ومبنى منه، وسجله في خرائط جوالك، فالطرق والمخيمات تتشابه كثيرا في منى. ويمكنني حفظ موقعه من جوالك ثم أدلك عليه.","سجل رقم المنطقة والشارع والمخيم في جوالك، وإن كانت حملتك تستخدم القطار فاعرف رقم المحطة القريبة من المخيم.","لا تخرج إلا للضرورة أو لأداء الشعائر، وبعد إبلاغ مسؤولي الحملة، ومع رفقة، واحمل جوالك وبطاقة نسك وما يدل على تبعيتك للمخيم."]},
 {t:"المبيت بمنى أيام التشريق",s:["hj","hgen","mn"],h:1,k:["المبيت بمني","المبيت في مني","ليالي مني","هل المبيت بمني واجب","ايام التشريق","التكبير في ايام التشريق","يوم القر"],
  a:["المبيت في منى ليلتي الحادي عشر والثاني عشر واجب، ويجوز ليلة الثالث عشر لمن لم يتعجل.","أيام التشريق (11 و12 و13 من ذي الحجة) أيام عيد وأكل وشرب وذكر لله، ويستحب فيها الإكثار من التكبير خاصة بعد الصلوات المفروضة.","ومن صيغه: الله أكبر الله أكبر، لا إله إلا الله، الله أكبر الله أكبر، ولله الحمد."]},
 {t:"يوم عرفة والوقوف بعرفة",s:["af","hj"],h:1,k:["يوم عرفه","الوقوف بعرفه","وقت الوقوف بعرفه","متى الوقوف بعرفه","اليوم التاسع","عرفه كلها موقف","متى نطلع من عرفه","متى نخرج من عرفه","صيام يوم عرفه","اصوم يوم عرفه","صلاه الظهر في عرفه"],
  a:["يوم عرفة هو التاسع من ذي الحجة، والوقوف بعرفة أعظم أركان الحج.","يبدأ الوقت بعد زوال الشمس ولا يغادر الحاج عرفة إلا بعد غروبها. ويمكنك الوصول قبل ذلك والمغادرة بعده حسب ما يتيسر، مع التقيد بمواعيد حملتك وتفويجها.","تصلي الظهر والعصر جمعا وقصرا مع جماعة حملتك بعد الزوال، وعرفة كلها موقف، فالتزم بحدودها الموضحة باللوحات.","لا يشرع للحاج صيام يوم عرفة، فقد كان النبي صلى الله عليه وسلم مفطرا فيه، ليتقوى على الدعاء، ويشرع صيامه لغير الحاج."]},
 {t:"موقع عرفة وحدودها",s:["af","hgen"],h:1,k:["موقع عرفه","حدود عرفه","مساحه عرفه","كم تبعد عرفه","المسافه الى عرفه","عرفات وين"],
  a:["عرفة منطقة واسعة خارج حدود الحرم تحيط بها الجبال، تقع شرق مكة المكرمة بين الطريقين المؤديين إلى الطائف، ومساحتها نحو 10.4 كيلومتر مربع.","تبعد عن منى نحو 10 كيلومترات، وعن المسجد الحرام نحو 20 كيلومترا، وعن وسط مزدلفة نحو 6 كيلومترات.","الوقوف خارج حدود عرفة من الأخطاء الشائعة، فالتزم بحدودها الموضحة باللوحات."]},
 {t:"جبل عرفة (جبل الرحمة)",s:["af","hgen"],h:1,k:["جبل عرفه","جبل الرحمه","جبل عرفات","صعود الجبل","اصعد الجبل","نطلع الجبل"],
  a:["يقع شرق عرفة، وهو مرتفع صغير على قمته شاخص بارتفاع 7 أمتار.","ليس على الحاج قصد الجبل ولا صعوده، فلم يصعده النبي صلى الله عليه وسلم ولا الصحابة، وقال: وقفت ها هنا وعرفة كلها موقف. وصعوده ظنا أن له فضلا خاصا من الأخطاء الشائعة."]},
 {t:"مسجد نمرة وخطبة عرفة",s:["af"],h:1,k:["مسجد نمره","نمره","خطبه عرفه","اصلي في نمره","الصلاه في نمره"],
  a:["بني في المكان الذي صلى فيه النبي صلى الله عليه وسلم وخطب خطبة الوداع، وتقام فيه صلاتا الظهر والعصر وتلقى خطبة يوم عرفة التي تنقل مباشرة عبر التلفزيونات والإذاعات.","وتجنبا للضياع وضربة الشمس، يوصي الدليل بأن تصلي في مخيمك ولا تخرج إلا للضرورة، بدل محاولة الوصول إلى مسجد نمرة."]},
 {t:"كيف أقضي يوم عرفة",s:["af","hgen"],h:1,k:["دعاء يوم عرفه","ماذا افعل في عرفه","وش اسوي في عرفه","ايش اسوي في عرفه","فضل يوم عرفه","كيف اقضي يوم عرفه","بماذا ادعو في عرفه"],
  a:["ابق في مخيمك ولا تخرج إلا لحاجة، فطرق عرفة تتشابه جدا ويكثر الضياع فيها.","نوع عباداتك بين الدعاء والتلبية وتلاوة القرآن والذكر، وادع الله بلغتك وبخيري الدنيا والآخرة، وادع لوالديك وأهلك وأصحابك بأسمائهم، ويمكنك الاستعانة بورقة تذكرك بدعواتك.","قال النبي صلى الله عليه وسلم: خير الدعاء دعاء يوم عرفة. وتجنب الانشغال بالتصوير ووسائل التواصل بدل الدعاء."]},
 {t:"ما أحمله معي إلى عرفة",s:["af"],h:1,k:["ماذا احمل لعرفه","احمل معي الى عرفه","اخذ معي الى عرفه","اخذ معي لعرفه","احمل معي لعرفه","احمل الى عرفه","وش اخذ معي لعرفه","ايش اخذ معي لعرفه","قائمه عرفه","اغراض عرفه","احتياجات عرفه","شنطه عرفه"],
  a:["شاحن جوال متنقل، والأدوية الشخصية، وكريمات التسلخات الجلدية، وحذاء مريح للمشي الطويل، ومحفظة للأغراض الشخصية.","سوار ركوب القطار، والبطاقة التعريفية وبطاقة نسك، ومصحف، ومظلة شمسية."]},
 {t:"الحر وصحتك في المشاعر",s:["hgen","af","mn"],h:1,k:["الحر في عرفه","الحر في مني","الحر في المشاعر","ضربه شمس في عرفه","ضربه الشمس في مني","الاجهاد الحراري","وقت اشتداد الحر","اشتداد الحراره","متى اطلع من المخيم"],
  a:["احرص على البقاء في المخيم خلال أوقات اشتداد الحرارة من الساعة 10 صباحا إلى الساعة 4 عصرا، والتزم بتعليمات التفويج والتنقل.","اشرب الماء باستمرار حتى إن لم تشعر بالعطش، فالحر والازدحام قد يؤديان إلى الجفاف سريعا، وتجنب الخروج تحت الشمس لغير حاجة، واستخدم المظلة الشمسية.","خذ قسطا كافيا من النوم وتجنب السهر، ولا تشتر الأطعمة من الباعة المتجولين، واغسل الفواكه والخضروات قبل تناولها، والبس الكمامة في الزحام."]},
 {t:"التفويج من عرفة إلى مزدلفة",s:["af","hgen"],h:1,k:["التفويج الى مزدلفه","النفره","النفره من عرفه","متى نروح مزدلفه","الانتقال الى مزدلفه","الذهاب الى مزدلفه"],
  a:["يبدأ التفويج إلى مزدلفة بعد غروب الشمس وفق الجداول المعتمدة، فتقيد بالوقت الذي يحدده المطوف للخروج من المخيم حتى لا تواجه الزحام والضياع.","كن مستعدا واحمل كل أغراضك، ولا تزاحم ولا تستعجل، وتقيد بالوسيلة المعدة لحملتك حافلة كانت أو قطارا.","استخدم دورات المياه قبل الخروج، فقد يتأخر وصولك إلى مزدلفة لأسباب عديدة."]},
 {t:"قطار المشاعر",s:["af","jm","nh"],h:1,k:["قطار المشاعر","سوار القطار","محطه القطار في مني","القطار في عرفه","تعليمات القطار","قطار مني"],
  a:["تقيد بالجدول الزمني لتفويج الحجاج إلى محطات القطار، وبتعليمات المرشد والمراقب ورجل الأمن، وحافظ على السوار في معصمك طوال موسم الحج.","امتنع عن حمل الأمتعة داخل القطار، والتزم الهدوء ولا تتدافع عند الصعود والنزول، ولا تفترش المحطات أو تستلق فيها.","قطار المشاعر لا يصل إلى الحرم، ولذا توفر بعض الحملات حافلات من مواقع التجمع إلى الحرم."]},
 {t:"المبيت بمزدلفة",s:["mz","hj"],h:1,k:["مزدلفه","المبيت بمزدلفه","المبيت في مزدلفه","كم نجلس في مزدلفه","كم نبقى في مزدلفه","متى نطلع من مزدلفه","ماذا افعل في مزدلفه","وش اسوي في مزدلفه","ايش اسوي في مزدلفه","صلاه المغرب في مزدلفه"],
  a:["يبدأ وقت المبيت بمزدلفة بعد غروب شمس يوم عرفة، وفيها تصلي المغرب والعشاء جمعا وقصرا مع حملتك، وستجد سجادا للنوم ووجبات خفيفة ودورات مياه.","تتنوع المذاهب في القدر اللازم للبقاء: فمنهم من يرى أن المرور بقدر وضع الرحل يكفي، ومنهم من يرى البقاء إلى منتصف الليل أو ثلثيه أو حتى الفجر. وقد بقي النبي صلى الله عليه وسلم حتى صلى الفجر ثم انصرف إلى منى، وأذن للنساء وكبار السن ومن معهم بالخروج بعد منتصف الليل، فالتزم بموعد حملتك.","خذ قسطك من النوم استعدادا ليوم العيد، وأكثر من الذكر والتلبية في يقظتك."]},
 {t:"مسجد المشعر الحرام",s:["mz"],h:1,k:["المشعر الحرام","مسجد المشعر الحرام","مسجد مزدلفه"],
  a:["أقيم في المكان الذي نزل فيه النبي صلى الله عليه وسلم بمزدلفة في حجة الوداع، ويقع بين طريق المشاة الرابع وطريق الملك فيصل، في المنتصف بين مسجد نمرة ومسجد الخيف.","يبعد نحو 5 كيلومترات عن مسجد الخيف ونحو 7 كيلومترات عن مسجد نمرة، وطوله 90 مترا وعرضه 56 مترا، ويستوعب أكثر من 12 ألف مصل."]},
 {t:"موقعك في مزدلفة",s:["mz"],h:1,k:["تهت في مزدلفه","ضعت في مزدلفه","مكان حملتي في مزدلفه","دورات المياه في مزدلفه","الحمامات في مزدلفه"],
  a:["ابق في حدود مكان حملتك ولا تغادره إلا للضرورة، واحفظ الموقع في خرائط جوالك، وحدد أهم معلم قريب بوضوح، ولتكن معك رفقة، واحمل بطاقة نسك دائما.","تنتشر دورات المياه والمواضئ في أنحاء مزدلفة، وبالقرب من مكان نزولك منطقة مخصصة لها، واحدة للرجال وأخرى للنساء."]},
 {t:"حصى الجمرات: الالتقاط والصفة",s:["mz","jm"],h:1,k:["الحصى","حصى الجمرات","التقاط الحصى","التقاط الجمرات","حجم الحصى","كم حصاه","من وين اجيب الحصى","من اين الحصى","غسل الحصى","اغسل الحصى","الجمار"],
  a:["للحاج أن يلتقط قبل خروجه من مزدلفة 7 حصيات لرمي جمرة العقبة يوم العيد، ويجوز التقاطها من منى أو أي مكان، وتوفر معظم الحملات اليوم حصى الرمي ولا حرج في استخدامه.","يلتقط حصى بقية الأيام من منى أو من أي مكان في طريقه، ولا يحسن التقاطه كله من مزدلفة.","الحصاة أصغر من البندق، قريبة من حبة البازلاء أو نواة التمر، دون تكلف في شكلها، ولا يشرع غسلها ولا تطييبها.","واحذر التقاط الحصى من أماكن السير حتى لا تؤذي نفسك وغيرك."]},
 {t:"أعمال يوم النحر وترتيبها",s:["nh","hj"],h:1,k:["يوم النحر","اعمال يوم النحر","اعمال يوم العيد","ترتيب اعمال يوم النحر","اليوم العاشر","قدمت عمل على عمل","هل يلزم الترتيب","يوم الحج الاكبر","ماذا افعل يوم العيد","وش اسوي يوم العيد"],
  a:["يوم النحر هو العاشر من ذي الحجة، أول أيام عيد الأضحى، وفيه معظم أعمال الحج: رمي جمرة العقبة، وذبح الهدي لمن عليه هدي، والحلق أو التقصير، وطواف الإفاضة، وسعي الحج.","أجاز النبي صلى الله عليه وسلم التقديم والتأخير في أعمال يوم النحر، فما سئل عن شيء قدم أو أخر إلا قال: افعل ولا حرج. واتبع برنامج حملتك في ترتيبها وأوقاتها.","لا تغادر المخيم يوم العيد إلا بعد التنسيق وأخذ الإذن من المطوف أو المشرف."]},
 {t:"رمي جمرة العقبة يوم العيد",s:["jm","nh"],h:1,k:["جمره العقبه","الجمره الكبرى","رمي جمره العقبه","متى ارمي جمره العقبه","وقت رمي جمره العقبه","رمي يوم العيد"],
  a:["جمرة العقبة أبعد جمرة عند قدومك وأقربها إلى مكة، وهي الوحيدة التي ترمى يوم العيد، بسبع حصيات مع التكبير عند كل رمية، ويتوقف الحاج عن التلبية عند رميها.","يبدأ وقتها بعد منتصف الليل لمن تعجل وخرج من مزدلفة ليلا، ويستمر كامل يوم العيد وليلته وينتهي بطلوع فجر الحادي عشر، والأفضل للقادر ألا يؤخرها إلى ذلك."]},
 {t:"الحلق والتقصير والتحلل في الحج",s:["nh","hj"],h:1,k:["اتحلل في الحج","نتحلل في الحج","التحلل الاول","التحلل الاصغر","التحلل الثاني","التحلل الكامل","التحلل في الحج","الحلق في الحج","التقصير في الحج","الحلاق في مني","الحلق يوم العيد"],
  a:["بعد رمي جمرة العقبة يحلق الرجل أو يقصر والحلق أفضل، وتجمع المرأة شعرها وتأخذ منه نحو 2 سم.","التحلل الأول (الأصغر) بفعل اثنين من ثلاثة: الرمي، والحلق أو التقصير، وطواف الإفاضة مع السعي لمن عليه سعي، فيحل له كل شيء إلا الجماع، ويشرع له الاغتسال والتطيب ولبس ما شاء. والتحلل الكامل بإتمام الثلاثة.","اختر حلاقا مرخصا في مكان مخصص، وتأكد أنه غسل يديه وغير أدواته ويستخدم أمواسا تستعمل مرة واحدة، واحذر حلاقي الطرقات."]},
 {t:"الهدي ومن يلزمه",s:["nh","hj"],h:1,k:["الهدي","ذبح الهدي","الذبيحه","من عليه هدي","ما وجدت الهدي","ما اقدر اذبح","صيام عشره ايام","التوكيل في الهدي","التوكيل في ذبح الهدي","قسائم الهدي","صك الهدي"],
  a:["يجب الهدي على المتمتع والقارن، ولا يجب على المفرد، ويكون من الإبل أو البقر أو الضأن أو الماعز، وتكفي البقرة أو الناقة عن سبعة.","من لم يستطع الهدي صام عشرة أيام: ثلاثة في الحج، وله أن يصومها في أيام التشريق، وسبعة إذا رجع إلى أهله.","يذبح في منى أو في مكة داخل حدود الحرم، والأيسر التوكيل بشراء قسائم ورقية أو إلكترونية من الجهات المعتمدة، مثل مشروع المملكة للإفادة من الهدي والأضاحي، واحذر الأفراد والجهات غير المرخصة."]},
 {t:"طواف الإفاضة وسعي الحج",s:["nh","hj"],h:1,k:["طواف الافاضه","طواف الزياره","طواف الحج","سعي الحج","متى طواف الافاضه","وقت طواف الافاضه","هل علي سعي","هل علي سعي ثاني"],
  a:["طواف الإفاضة ركن لا يصح الحج بدونه، ويسمى طواف الزيارة وطواف الحج، ويبدأ وقته من منتصف ليلة العيد لمن تعجل من مزدلفة وينتهي بانتهاء شهر ذي الحجة، وأده في الوقت الذي تحدده حملتك.","المتمتع يلزمه سعي الحج بعد طواف الإفاضة، أما المفرد والقارن فإن سعيا بعد طواف القدوم فلا سعي عليهما، وإلا سعيا بعد طواف الإفاضة.","لا تتوجه للطواف إلا بعد التنسيق مع حملتك، واحفظ موقع وقوف الحافلة ومكان التجمع، وجميع أدوار الحرم مهيأة للطواف في هذا اليوم وما بعده، وتتوفر عربات كهربائية ويدوية."]},
 {t:"رمي الجمرات في أيام التشريق",s:["jm","hj","hgen"],h:1,k:["رمي الجمرات","كيف ارمي","كيف ارمي الجمرات","ترتيب الجمرات","الجمره الصغرى","الجمره الوسطى","متى ارمي","وقت الرمي","الرمي قبل الزوال","كم حصاه كل يوم","الدعاء بعد الرمي"],
  a:["ترمي كل يوم من أيام التشريق الجمرات الثلاث بالترتيب، كل جمرة بسبع حصيات متفرقات مع التكبير، أي 21 حصاة في اليوم: تبدأ بالصغرى ثم تتنحى عن الطريق وتدعو مستقبلا القبلة، ثم الوسطى وتدعو، ثم جمرة العقبة ولا تقف بعدها للدعاء.","وقت الرمي بعد الزوال، وأيام التشريق كلها وقت للرمي حتى غروب شمس يوم 13، والتزم بالوقت الذي تحدده حملتك بالتنسيق مع الجهات المختصة. وفي مسائل الرمي والمبيت اسأل مفتي حملتك.","وجه رميك إلى الجدار وسط الجمرة لتسقط الحصاة في الحوض، واقترب من الجهة الأقل زحاما، ولا ترم الحصيات دفعة واحدة، واحرص ألا تؤذي أحدا."]},
 {t:"الوصول إلى الجمرات وجسر الجمرات",s:["jm","mn"],h:1,k:["جسر الجمرات","منشاه الجمرات","كيف اوصل الجمرات","كيف اروح الجمرات","الطريق الى الجمرات","ادوار الجمرات","عربات الجولف في الجمرات","الجمرات وين"],
  a:["يصل الحجاج إلى الجمرات بقطار المشاعر ثم مشيا، أو بالحافلات المخصصة لمجموعة من الحملات، أو مشيا مع مظلة شمسية وحذاء مريح، وتتوفر عربات جولف مكشوفة لكبار السن ومن يثقل عليه المشي عند صعود الجسر.","التزم بطريق حملتك والدور المحدد لها وأوقات التفويج، وبتوجيهات رجال الأمن، وتنتشر فرق إسعافية حول الجمرات.","يتكون جسر الجمرات من 5 طوابق، فيه 11 مدخلا و12 مخرجا ونظام تبريد يخفض الحرارة إلى 29 درجة، وأكثر من 900 كاميرا و328 سلما كهربائيا، و4 أنفاق تربطه بمكة."]},
 {t:"التوكيل في الرمي",s:["jm","hj"],h:1,k:["التوكيل في الرمي","التوكيل بالرمي","وكل من يرمي","اوكل من يرمي","ارمي عن امي","ارمي عن ابوي","ارمي عن غيري","ما اقدر ارمي","الانابه في الرمي"],
  a:["يجوز لكبير السن والضعيف والمريض والحامل ومن يخشى على نفسه الضرر أن يوكل من يرمي عنه من الحجاج.","يرمي الوكيل عن نفسه أولا ثم عمن أنابه عند كل جمرة، ثم ينتقل إلى التي تليها."]},
 {t:"التعجل والتأخر ومغادرة منى",s:["mn","jm","hj"],h:1,k:["التعجل","التاخر","المتعجل","اتعجل","نتعجل","مغادره مني","متى نطلع من مني","اليوم الثاني عشر","اليوم الثالث عشر"],
  a:["يجوز أن تتعجل فتخرج من منى يوم 12، أو تتأخر فتخرج يوم 13. ومن أراد التعجل فلا بد أن يغادر منى قبل الغروب، فإن غربت الشمس وهو فيها وجب عليه المبيت.","المتعجل يرمي يوم 11 ثم يوم 12 فقط، ولا يرمي يوم 12 رميا ثانيا عن يوم 13.","التعجل أو التأخر بحسب برنامج حملتك، فتقيد بمواعيد التفويج، واجمع أمتعتك قبل المغادرة بوقت كاف، واشحن جوالك، ورافق حجاج حملتك."]},
 {t:"مساجد منى: الخيف والبيعة",s:["mn","hgen"],h:1,k:["مسجد الخيف","الخيف","مسجد البيعه","مساجد مني"],
  a:["مسجد الخيف أعظم مساجد منى، على طريق الملك فيصل، في الموضع الذي صلى فيه النبي صلى الله عليه وسلم في حجة الوداع، ومساحته نحو 25 ألف متر مربع ويتسع لنحو 45 ألف مصل.","مسجد البيعة أسفل جبل ثبير المطل على ساحات الجمرات، في موضع بيعة العقبة، على يسار الذاهب إلى منى وعلى بعد نحو 300 متر من جمرة العقبة."]},
 {t:"طواف الوداع",s:["hj","mn"],h:1,k:["طواف الوداع","الوداع","هل الوداع واجب","الحائض والوداع","متى طواف الوداع","نسيت طواف الوداع"],
  a:["طواف الوداع آخر محطات الحج: تطوف بعد خروجك من منى وقبل مغادرة مكة ثم تسافر مباشرة، وهو واجب ومن تركه فعليه دم.","يسقط عن الحائض والنفساء، ومن أخر طواف الإفاضة حتى خروجه من مكة كفاه عن طواف الوداع.","تقيد بمواعيد مشرف الحملة في وقت المغادرة وموعد طواف الوداع."]},
 {t:"الفتوى في الحج",s:["hgen","hj"],h:1,k:["فتوى في الحج","رقم الفتوى في الحج","مفتي الحمله","الدعاه في المخيم"],
  a:["يتوفر في السكن والمخيمات دعاة متخصصون بلغات مختلفة، وللفتوى يذكر دليل الحاج العام الرقم 8002451000.","وفي الاختلافات الفقهية ومسائل المبيت والرمي راجع مفتي حملتك."]}
];
