const HAJ_CTX=/ (حج|الحج|للحج|بالحج|حاج|الحاج|حجاج|الحجاج|حجي|حجنا|مني|بمني|عرفه|بعرفه|عرفات|مزدلفه|بمزدلفه|الجمرات|التشريق|النحر|العيد|المشاعر) /;
