function kbMatch(text){const n=kbNorm(text);if(n.trim().length<3)return null;let best=null;
  for(const e of KB){if(!kbSiteOk(e,n))continue;let s=0;for(const k of e.k){const kk=normAr(k);if(kk&&n.includes(" "+kk))s+=kk.includes(" ")?4:3}if(s&&normAr(e.t)&&n.includes(normAr(e.t)))s+=2;if(s&&e.h&&HAJ_CTX.test(n))s+=2;if(s>(best?best.s:0))best={e,s}}
  return best&&best.s>=3?best:null}
